INSERT INTO "strategy_changes" VALUES(1,'2026-09-28T22:03:00Z','mm-1.0.0','mm-2.0.0','389313b22ae633d70f0881a8b34067458eb84ec5fac14d02d970b801dc3bc6de','02451982e192530ea77d7cae430fd4b483500177ab7ba69ea3bf808b0ec27179','next decision after 2026-09-28 deployment','Market maker v2: size atomic quote pairs by one-sided loss, limit inventory and resting orders, hedge using actual acquisition cost, volume-limit fills, exclude estimated rebates from cash. Current marks, persistent daily stops and protected profit budget; robust delayed settlement.','research/revamp_2026_09_28/SUMMARY.md: 62 tests passed; independent review; fixed-variant replay at 1m/5m. Drawdown improved but returns lower; no claim of proven profit.');
INSERT INTO "strategy_changes" VALUES(2,'2026-09-29T02:15:36Z','mm-2.0.0','mm-2.1.0','02451982e192530ea77d7cae430fd4b483500177ab7ba69ea3bf808b0ec27179','3e0fd641d2eb3f9201aa55155205deb33b653715e5bd48157d2b668847d4424d','next decision','mm-2.0.0 -> mm-2.1.0. Bids stay at least 0.5c below their own midpoint (rounded down to tick, pair cost still capped at 98c), same input-quality gate as crypto2, and a 60-minute new-market cooldown after two net-losing settled markets in 240 minutes (existing inventory may still be completed within risk limits). Exposure limits unchanged.','Adapted from Hummingbot spread-vs-reference/tick-rounding, Freqtrade StoplossGuard (net per market, not per leg) and OctoBot freshness (research/upstream_2026_09_28/PLAN.md). 99 unit tests pass. No profitability evidence; forward paper results only.');
INSERT INTO "strategy_changes" VALUES(3,'2026-10-05T08:00:58Z','mm-2.1.0','mm-2.2.0','3e0fd641d2eb3f9201aa55155205deb33b653715e5bd48157d2b668847d4424d','a8251df6bb7fb72f1052dfc179cfb9ea95ab33cb7139efd34be49979755d8b0a','next decision','Pause new market-maker quotes (max_open_markets=0); existing positions still settle. Risk-reducing; no other parameter changed.','research/review_2026_10_05/mm_replay_output.txt: replay of the quoting rule on 2,306 settled 15m BTC/ETH markets measured about -0.7 per 10-share market (-13 s.e., both halves, both queue assumptions); the live book lost about -0.53 per market over 14 markets. Replay fill model is optimistic and ignores rebates (~0.4 total live), so it measures adverse selection, not tradable P&L.');
